with a as(select * from public.authors where open_library_id=any(array['OL28257A','OL22258A','OL24837A','OL18865A']::text[])),w as(select * from public.works where open_library_id=any(array['OL46873W','OL167160W','OL14871640W','OL443606W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780345917270','9780446694216','9780739420416','9786054482542','9789010018052','9789044358490','9789046113677','9789026997501']::text[]) or open_library_edition_id=any(array['OL10686520M','OL10263160M','OL10658842M','OL35611866M','OL42854732M','OL61374864M','OL47139245M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987105001 and 987105999),'editions',(select count(*) from public.editions where id between 987205001 and 987205999),'authors',(select count(*) from public.authors where id between 987305001 and 987305999))) as preflight;
